/* UI prototype. No resumes, LinkedIn data or profiles leave the browser. */
const DM=window.SycamoreMatch, DO=window.SycamoreOpportunities;
const ds={mode:'experience',topic:'accounting',day:'any',transport:'transit',maxTravel:45,weeks:12,maxCost:15,cause:'any',reviewed:false,skills:[],tab:'recommended',saved:new Set(),hidden:new Set(),showFilters:false,text:'',linkedin:'',draftSkills:[],draftReviewed:false};
try{const saved=JSON.parse(localStorage.getItem('sycamore-discover-saved')||'[]');ds.saved=new Set(saved.filter(id=>DO.some(o=>o.id===id)))}catch{}
function dSave(){try{localStorage.setItem('sycamore-discover-saved',JSON.stringify([...ds.saved]))}catch{}}
function dSelect(name,value){ds[name]=['maxTravel','weeks','maxCost'].includes(name)?Number(value):value;render()}
function dMode(mode){ds.mode=mode;render()}
function dBookmark(id){ds.saved.has(id)?ds.saved.delete(id):ds.saved.add(id);dSave();render();notify(ds.saved.has(id)?'Saved on this device. No application submitted.':'Removed from your saved list.')}
function dHide(id){ds.hidden.add(id);render();notify('Hidden from recommendations. You can still find it under Browse all.')}
function dScore(r){return r.low===r.high?`${r.low}`:`${r.low}–${r.high}`}
function dOptions(values,current){return values.map(([v,t])=>`<option value="${esc(v)}" ${String(current)===String(v)?'selected':''}>${esc(t)}</option>`).join('')}
function dFilter(){return `<section class="card"><span class="eyebrow">MAKE IT YOURS</span><h3 style="margin:10px 0 20px">What matters to you?</h3><label class="field">I want to explore<select onchange="dSelect('topic',this.value)">${dOptions(Object.entries(DM.topics).map(([k,v])=>[k,v.name]),ds.topic)}</select></label><label class="field">Available day<select onchange="dSelect('day',this.value)">${dOptions(['any','Saturday','Sunday','Wednesday'].map(x=>[x,x==='any'?'Any sample day':x]),ds.day)}</select></label><label class="field">How I travel<select onchange="dSelect('transport',this.value)">${dOptions([['transit','Public transport'],['car','Car'],['bike','Bike']],ds.transport)}</select></label><label class="field">Maximum one-way journey<select onchange="dSelect('maxTravel',this.value)">${dOptions([15,30,45,60,90].map(x=>[x,x+' minutes']),ds.maxTravel)}</select><small>Sample San José journeys, not live routes.</small></label><label class="field">Maximum commitment<select onchange="dSelect('weeks',this.value)">${dOptions([[1,'One event'],[2,'Up to 2 weeks'],[6,'Up to 6 weeks'],[12,'Up to 12 weeks']],ds.weeks)}</select></label><label class="field">Maximum travel cost per visit<select onchange="dSelect('maxCost',this.value)">${dOptions([0,5,10,15,25].map(x=>[x,'$'+x]),ds.maxCost)}</select></label><label class="field">A cause I care about<select onchange="dSelect('cause',this.value)">${dOptions(['any','Financial access','Community care','Environment','Food access','Education','Arts & culture'].map(x=>[x,x==='any'?'Open to any cause':x]),ds.cause)}</select></label><p class="discover-note">Your limits filter recommendations. Browse all to see other possibilities.</p><button class="btn secondary wide" onclick="dReset()">Reset preferences</button></section><section class="card tip"><span class="eyebrow">YOUR EXPERIENCE</span><h3 style="margin-top:10px">${ds.reviewed?'Reviewed by you':'A starting point, not a box.'}</h3><p class="discover-note">${ds.reviewed?esc(ds.skills.slice(0,5).join(' · ')||'No prior experience selected'):'Add a resume excerpt or select skills. You can also explore without one.'}</p><a href="#/discover/profile" class="textlink">${ds.reviewed?'Edit background':'Add my background'} →</a><p class="discover-note" style="margin:14px 0 0">Profile statements are self-reported, not organization-attested.</p></section>`}
function dReset(){Object.assign(ds,{mode:'experience',topic:'accounting',day:'any',transport:'transit',maxTravel:45,weeks:12,maxCost:15,cause:'any'});render()}
function dArt(o){return landscape(o.topic==='community'||o.topic==='accounting')}
function dStatus(r){return r.status==='excluded'?'Outside your limits':r.status==='conditional'?'Details to confirm':r.status==='training'?'Training first':'Explore this role'}
function dWhy(r){const o=r.opportunity;let direct=o.tags.filter(t=>ds.skills.includes(t));return o.topic===ds.topic?`A chance to practice ${DM.topics[ds.topic].name.toLowerCase()}. ${ds.reviewed&&direct.length&&ds.mode==='experience'?'Connects with your '+esc(direct.slice(0,2).join(' and '))+' experience.':ds.mode==='interests'?'Your current interests lead the way; past experience has no ranking weight.':'The role includes '+esc(o.tasks[0].charAt(0).toLowerCase()+o.tasks[0].slice(1))+'.'}`:`${esc(o.outcome)} ${ds.mode==='interests'?'Outside your chosen interest area.':'A different direction to consider.'}`}
function dCard(r){const o=r.opportunity;return `<article class="card opportunity-card"><div class="opportunity-art">${dArt(o)}<span class="pill">${esc(o.kind)}</span></div><div class="opportunity-content"><span class="eyebrow" style="font-size:9px">ILLUSTRATIVE OPPORTUNITY</span><h3 style="margin-top:9px">${esc(o.role)}</h3><p class="org-name">${esc(o.org)} · San José demo area</p><span class="pill ${r.status==='ready'?'':'pending'}" style="align-self:start">${dStatus(r)}</span><div class="opportunity-meta"><span>${o.day} · ${o.time}</span><span>${o.weeks===1?'One event':o.weeks+' weeks'}</span><span>${r.travel===null?'Journey unconfirmed':r.travel+' min · sample '+ds.transport}</span></div><p class="opportunity-why">${dWhy(r)}</p><div class="fit-line"><strong>${dScore(r)} fit points</strong><small class="muted">${r.knownWeight<100?'Some details unknown':'Out of 100'}</small></div><div class="fit-meter" aria-hidden="true"><span style="width:${r.low}%"></span></div><p class="source-label" style="margin:9px 0 0">Sample listing · not an open application</p><div class="opportunity-actions"><a class="btn" href="#/discover/${o.id}">See role & fit ↗</a><button class="btn secondary save-opportunity" aria-label="${ds.saved.has(o.id)?'Unsave':'Save'} ${esc(o.role)}" aria-pressed="${ds.saved.has(o.id)}" onclick="dBookmark('${o.id}')">${ds.saved.has(o.id)?'✓':'+'}</button></div></div></article>`}
function discoverPage(){let all=DO.map(o=>DM.evaluate(o,ds)),ranked=DM.rank(DO,ds).filter(r=>!ds.hidden.has(r.opportunity.id));let items=ds.tab==='saved'?all.filter(r=>ds.saved.has(r.opportunity.id)):ds.tab==='all'?all:ranked;return `<section class="discover-hero"><div><span class="eyebrow">DISCOVER YOUR NEXT CHAPTER</span><h1>Find your kind of good.</h1><p>Bring what you know. Explore what you don’t.<br>Choose the service that means something to you.</p></div><div class="discover-orbit">${icon('leaf')}</div></section><div class="discover-heading"><div><span class="eyebrow">THREE WAYS TO START</span><h2 style="margin-top:6px">Your direction. Your choice.</h2></div><a class="textlink" href="#/discover/profile">${ds.reviewed?'Edit my background':'Add my background'} →</a></div><div class="discover-mode-grid">${Object.entries(DM.modes).map(([k,v])=>`<button class="discover-mode" aria-pressed="${ds.mode===k}" onclick="dMode('${k}')"><strong>${v}</strong><span>${k==='experience'?'Put your existing skills into practice.':k==='learn'?'Find support for your next first step.':'Let curiosity lead, whatever your major.'}</span></button>`).join('')}</div><div class="notice" style="font-size:12px">Interactive recommendation preview. All ${DO.length} listings, providers, journeys, and requirements below are fictional examples. Scoring works locally; Claude, LinkedIn import, and live opportunity search are not connected.</div><div class="discover-body"><aside class="discover-rail ${ds.showFilters?'expanded':''}" style="position:static;height:auto;border:0;background:transparent;padding:0;display:${ds.showFilters?'block':''}">${dFilter()}</aside><section><div class="discover-heading"><h2>${ds.tab==='saved'?'Your saved possibilities':ds.tab==='all'?'Room to explore':'Picked for your next chapter'}</h2><button class="btn secondary discover-mobile-filters" onclick="ds.showFilters=!ds.showFilters;render()">${ds.showFilters?'Hide preferences':'Preferences'} ☷</button></div><nav class="discover-tabs" aria-label="Opportunity lists">${[['recommended','For you'],['all','Browse all'],['saved','Saved ('+ds.saved.size+')']].map(([k,t])=>`<button aria-pressed="${ds.tab===k}" onclick="ds.tab='${k}';render()">${t}</button>`).join('')}</nav><p class="discover-count" role="status" aria-live="polite">${items.length} ${items.length===1?'possibility':'possibilities'} · ${esc(DM.topics[ds.topic].name)} · ${DM.modes[ds.mode]}</p>${ds.tab==='recommended'&&all.some(r=>r.status==='excluded')?'<p class="discover-note">Some sample roles are outside your limits. You can still inspect them in Browse all.</p>':''}${ds.hidden.size?'<button class="textlink" style="background:none;border:0;padding:10px 0" onclick="ds.hidden.clear();render()">Restore hidden recommendations ('+ds.hidden.size+')</button>':''}<div class="discover-grid">${items.map(dCard).join('')}</div>${items.length?'':`<div class="card empty"><h2>${ds.tab==='saved'?'Keep a possibility for later.':'No sample roles fit these limits.'}</h2><p class="muted">${ds.tab==='saved'?'Save a role using the + button.':'Try a different day, journey limit, or commitment—or browse all roles.'}</p><button class="btn secondary" onclick="ds.tab='all';render()">Browse all roles →</button></div>`}<details style="margin-top:25px"><summary class="textlink" style="cursor:pointer;min-height:44px">How your recommendations work</summary><div class="card"><p class="discover-note">We check your day, journey, cost, and commitment limits, then rank eligible sample roles using the nine-criterion matrix. Unknown experience or travel details produce a score range. Ranking uses the supported lower bound; ties use listing ID. Fit points are not probabilities, qualifications, or a hiring decision. All opportunities remain browsable.</p><div class="discover-note">${DM.criteria.map((c,i)=>`${c}: ${DM.weights[ds.mode][i]}%`).join(' · ')}</div><p class="discover-note">The weights are a design hypothesis, not validated outcomes. No school prestige, employer prestige, profile completeness bonus, or badge-count bonus is used.</p></div></details></section></div>`}
function dProfile(){return `<div class="discover-profile"><a class="textlink" href="#/discover">← Back to Discover</a><div class="intro" style="margin-top:20px"><div><span class="eyebrow">YOU’RE MORE THAN A MAJOR</span><h1>A little about your experience.</h1><p class="muted">Give your recommendations context. You decide what belongs.</p></div></div><div class="card"><span class="discover-step">01 · Add context</span><h2 style="margin-top:10px">Start with what you’ve done</h2><p class="discover-note">Paste a resume excerpt, type a few responsibilities, or load a fictional profile. Text stays in this page’s memory and clears on refresh. This preview uses a small keyword dictionary—not Claude—to suggest tags.</p><label class="field" for="background-text">Experience and responsibilities</label><textarea id="background-text" placeholder="For example: club treasurer; tracked expenses in Excel; helped organize community events." oninput="ds.text=this.value">${esc(ds.text)}</textarea><div class="discover-field-row" style="margin:14px 0"><button class="btn secondary" onclick="dSample()">Try sample finance profile</button><label class="textlink" style="cursor:pointer">Import text resume<input type="file" accept=".txt,.md,text/plain,text/markdown" style="display:block;font-size:12px;margin-top:7px;max-width:100%" onchange="dReadFile(this)"></label></div><p class="discover-note">Text and Markdown only, up to 200 KB. For PDF or Word, paste the relevant text.</p><label class="field" style="margin-top:20px">LinkedIn profile URL · optional<input type="url" id="linkedin-reference" placeholder="https://www.linkedin.com/in/your-profile" value="${esc(ds.linkedin)}" oninput="ds.linkedin=this.value"></label><p class="discover-note">Reference only. This preview does not fetch LinkedIn profiles. Paste the experience you want considered above.</p><button class="btn wide" onclick="dExtract()">Review suggested experience →</button></div><div class="card" id="experience-review"><span class="discover-step">02 · Review and choose</span><h2 style="margin-top:10px">Does this sound like you?</h2><p class="discover-note">Tags are suggestions from words in your text. Remove anything inaccurate or add a skill yourself. Selecting a tag does not verify proficiency.</p><div class="skill-tags">${ds.draftSkills.map(s=>`<button class="skill-tag" aria-pressed="true" onclick="dRemoveSkill('${s}')">${esc(s)} ×</button>`).join('')||'<span class="muted" style="font-size:13px">No skills selected yet. Add your own or explore as a beginner.</span>'}</div><div class="discover-field-row"><label class="field" style="flex:1;margin:0">Add a skill<select id="manual-skill">${dOptions(Object.keys(DM.skillRules).map(s=>[s,s]),'budgeting')}</select></label><button class="btn secondary" style="align-self:end" onclick="dAddSkill()">Add</button></div><label class="discover-field-row" style="font-size:13px;margin:20px 0"><input type="checkbox" id="review-confirm" ${ds.draftReviewed?'checked':''} onchange="ds.draftReviewed=this.checked"> I reviewed these tags, including an empty list if I’m starting fresh.</label><button class="btn wide" onclick="dConfirmProfile()">Use this background</button><button class="btn secondary wide" style="margin-top:10px" onclick="dSkipProfile()">Explore without a resume</button><p class="discover-note" id="review-error" role="alert"></p></div></div>`}
function dSample(){ds.text='Sample student: Club treasurer. Built an Excel budget and tracked event expenses. Organized a community fundraiser and presented a spending summary.';ds.draftSkills=[];ds.draftReviewed=false;render();notify('Fictional finance profile loaded. Review suggested experience next.')}
async function dReadFile(input){const f=input.files[0];if(!f)return;if(f.size>204800||!(/\.(txt|md)$/i.test(f.name))){notify('Choose a .txt or .md file under 200 KB.');input.value='';return}try{ds.text=await f.text();ds.draftReviewed=false;render();notify('Text loaded locally. Review it before using it.')}catch{notify('Could not read this text file. Please paste the excerpt.')}}
function dExtract(){ds.draftSkills=DM.extract(ds.text);ds.draftReviewed=false;render();document.getElementById('experience-review').scrollIntoView({behavior:'smooth',block:'start'});notify('Review suggested tags. They are not verified skills.')}
function dRemoveSkill(s){ds.draftSkills=ds.draftSkills.filter(x=>x!==s);ds.draftReviewed=false;render()}
function dAddSkill(){const value=document.getElementById('manual-skill').value;if(!ds.draftSkills.includes(value))ds.draftSkills.push(value);ds.draftReviewed=false;render()}
function dConfirmProfile(){if(!ds.draftReviewed){document.getElementById('review-error').textContent='Please review the tags and check the confirmation box first.';return}ds.skills=[...ds.draftSkills];ds.reviewed=true;go('/discover');notify('Background updated for this page session.')}
function dSkipProfile(){ds.skills=[];ds.reviewed=false;ds.draftSkills=[];ds.draftReviewed=false;go('/discover');notify('You can explore without a resume. Unknown experience stays unknown.')}
function dDetail(id){const o=DO.find(o=>o.id===id);if(!o)return '<h1>Opportunity not found</h1><a class="btn" href="#/discover">Back to Discover</a>';const r=DM.evaluate(o,ds);return `<a class="textlink" href="#/discover">← All possibilities</a><div class="intro" style="margin-top:22px"><div><span class="eyebrow">${esc(o.kind)} · ILLUSTRATIVE ROLE</span><h1 class="discover-detail-title">${esc(o.role)}</h1><p class="muted">${esc(o.org)}</p></div></div><div class="detailgrid"><section class="fit-detail"><div class="card"><span class="pill ${r.status==='ready'?'':'pending'}">${dStatus(r)}</span><h2 style="margin-top:20px">A real contribution starts with clear tasks.</h2><ul>${o.tasks.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><div class="discover-callout"><strong>What you could practice</strong><p style="margin:8px 0 0">${esc(o.outcome)} This describes an opportunity, not a guaranteed learning outcome.</p></div><div class="opportunity-meta"><span>${o.day} · ${o.time}</span><span>${o.weeks===1?'One event':o.weeks+' weeks'}</span><span>San José demo area</span></div><h3>Before you join</h3><p class="discover-note">${esc(o.training||'A beginner orientation is included in this sample role. Actual requirements must be confirmed with the organizer.')}</p><p class="discover-note">${esc(o.supportNote)}</p>${r.reasons.length?`<div class="notice error"><strong>Outside your current limits</strong><ul>${r.reasons.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></div>`:''}${r.status==='conditional'?'<div class="notice">Travel time or cost is unknown. Confirm the missing details before deciding.</div>':''}</div><div class="card"><h2>Your fit, explained.</h2><p class="discover-note">${dWhy(r)}</p><div class="fit-line"><strong>${dScore(r)} fit points / 100</strong><span class="pill">${DM.modes[ds.mode]}</span></div><div class="fit-meter"><span style="width:${r.low}%"></span></div><p class="discover-note">${r.knownWeight<100?'Some criteria are unknown. The range shows the minimum and maximum possible total, not a statistical confidence interval.':'Calculated from the ratings and weights below.'} Fit points are not a probability or a qualification.</p><table class="fit-table"><thead><tr><th scope="col">Criterion & evidence</th><th scope="col">Weight</th><th scope="col">Rating</th><th scope="col">Points</th></tr></thead><tbody>${r.components.map(c=>`<tr><td>${c.name}<small>${esc(c.explanation)}</small></td><td>${c.weight}%</td><td>${c.weight===0?'—':c.rating===null?'?':c.rating+'/5'}</td><td>${c.weight===0?'0':c.points===null?'0–'+c.weight:Number(c.points.toFixed(1))}</td></tr>`).join('')}</tbody><tfoot><tr><th scope="row">Supported total</th><td>100%</td><td></td><td>${dScore(r)}</td></tr></tfoot></table><details><summary>How to read the matrix</summary><p class="discover-note">Known ratings range from 0 (no alignment) to 5 (direct alignment). Each contribution is weight × rating ÷ 5. Unknown criteria contribute a range from zero to their full weight. Zero-weight criteria do not affect your score. These weights and the small skill map are unvalidated design choices.</p></details></div></section><section><div class="card tip"><span class="eyebrow">YOUR NEXT STEP</span><h3 style="margin-top:12px">Keep this possibility.</h3><p class="discover-note">This is a fictional listing for trying the recommendation experience. There is no application or reserved place.</p><button class="btn wide" onclick="dBookmark('${o.id}')">${ds.saved.has(o.id)?'✓ Saved · remove':'Save this opportunity +'}</button><a class="btn secondary wide" style="margin-top:10px" href="#/discover/profile">Review my background</a><p class="discover-note" style="margin:15px 0 0">Saved roles stay on this device. Resume text and skill selections clear on refresh.</p></div><div class="card"><h3>Source & requirements</h3><p class="source-label">Fictional fixture · no verified opening</p><p class="discover-note">Provider, schedule, route estimates, costs, and tasks are sample data. The role has not been independently checked. A real listing will include an organizer URL and a last-checked date.</p>${o.id==='tax'?'<p class="discover-note">VITA is a real program type; this sample provider and opening are fictional.</p><a class="textlink" href="https://www.irs.gov/individuals/irs-tax-volunteers" target="_blank" rel="noopener noreferrer">Explore real VITA volunteering at IRS.gov ↗</a>':''}</div><div class="card discover-feedback"><h3>Not your direction?</h3><p class="discover-note">Your experience should never box you in.</p><button class="btn secondary wide" onclick="dHide('${o.id}');go('/discover')">Hide from my recommendations</button><a class="textlink" style="display:block;margin-top:15px" href="#/discover">Change my interests →</a></div></section></div>`}
const discoverPriorLayout=layout;layout=function(body){let h=discoverPriorLayout(body);h=h.replace(navItem('/','Overview','home'),navItem('/','Overview','home')+navItem('/discover','Discover','leaf'));h=h.replace(navItem('/journey','Journey','records'),navItem('/discover','Discover','leaf'));h=h.replace('PHASE 1 PREVIEW · Sample service records · Explore the desktop and phone layouts','INTERACTIVE PREVIEW · Sample records & opportunities · Your choice comes first');if(getPath().startsWith('/discover')){h=h.replace(' / Overview',' / Discover');h=h.replace('href="#/discover" class=""','href="#/discover" class="sel"');}return h};
const discoverPriorHome=home;home=function(){let h=discoverPriorHome();return `<section class="discover-banner"><div><span class="eyebrow">A LITTLE MORE YOU</span><h2>What would you like to do next?</h2><p>Build on your experience, try something new, or follow an interest.</p></div><a class="btn" href="#/discover">Discover opportunities ↗</a></section>`+h};
const discoverPriorRender=render;render=function(){const p=getPath();if(p==='/discover'||p==='/discover/profile'||p.startsWith('/discover/')){clearInterval(interval);document.getElementById('app').innerHTML=layout(p==='/discover'?discoverPage():p==='/discover/profile'?dProfile():dDetail(p.split('/')[2]));return}discoverPriorRender()};
render();
